from __future__ import annotations
import base64,json,re
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
VERSION='20260730-pojistime-rotation-1'
PHOTO=''''''

def shield(x,y,s=1):
 return f'<g transform="translate({x} {y}) scale({s})"><path d="M50 0 92 16v35c0 32-18 56-42 70C26 107 8 83 8 51V16Z" fill="#0b477b"/><path d="M50 11 82 23v27c0 24-13 43-32 56C31 93 18 74 18 50V23Z" fill="#65a829"/><path d="m33 52 11 11 24-29" fill="none" stroke="#fff" stroke-width="9" stroke-linecap="round" stroke-linejoin="round"/></g>'
def wrap(w,h,body):
 return f'<svg xmlns="http://www.w3.org/2000/svg" width="{w}" height="{h}" viewBox="0 0 {w} {h}"><defs><linearGradient id="bg" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#fff"/><stop offset="1" stop-color="#eef6fb"/></linearGradient><linearGradient id="blue" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#073a69"/><stop offset="1" stop-color="#07558b"/></linearGradient><filter id="s"><feDropShadow dy="8" stdDeviation="10" flood-opacity=".18"/></filter></defs>{body}</svg>'
def photo(x,y,w,h): return f'<image x="{x}" y="{y}" width="{w}" height="{h}" preserveAspectRatio="xMidYMid slice" href="data:image/webp;base64,{PHOTO}"/>'
def text(x,y,size,fill,value,weight=800): return f'<text x="{x}" y="{y}" font-family="Arial,sans-serif" font-size="{size}" font-weight="{weight}" fill="{fill}">{value}</text>'
